function contextBar(){return `<section class="context-bar" aria-label="Comparison context"><label>Comparison population<select id="cohort">${cohorts.map(c=>`<option value="${c.id}" ${state.cohort===c.id?'selected':''}>${c.name}</option>`).join('')}</select></label><div class="condition-control"><span>Assessment condition</span>${modeToggle()}</div><div class="context-date"><span>AS OF ${esc(state.asOf)}</span><small>Frozen synthetic reference · v2</small></div></section>`;}
