function peopleView(){let person=personById(selectedPersonId),pool=state.benchmarkVisible?cohortPeople(state.cohort):[];if(!person||!pool.includes(person)){person=justAhead(state,selectedSkill)?.person||pool[0];selectedPersonId=person?.id;}
const result=comparePeople(state,person),row=result.rows?.find(r=>r.skill===selectedSkill),near=pool.map(p=>({p,score:participantEstimate(p,selectedSkill,state.mode,state.asOf)})).filter(x=>x.score!==null).sort((a,b)=>Math.abs(a.score-(estimate(state,selectedSkill).score??0))-Math.abs(b.score-(estimate(state,selectedSkill).score??0))).slice(0,5);
return `${pageHead('REAL COMPARISON. A CLEARER NEXT STEP.','Compare us.','Not a story about someone’s character. A comparison of what the evidence demonstrates.')} ${contextBar()} ${populationNote()}<div class="people-controls"><label>Find the next person ahead in<select id="capability-select">${skills.map(s=>`<option value="${s.id}" ${selectedSkill===s.id?'selected':''}>${s.name}</option>`).join('')}</select></label><label>Choose a reference person<select id="person-select">${pool.map(p=>`<option value="${p.id}" ${p.id===person?.id?'selected':''}>${p.displayName} · synthetic</option>`).join('')}</select></label></div><div class="compare-layout">${nextPersonCard(selectedSkill,true)}<section class="card comparison-card"><div class="comparison-title"><div><span class="eyebrow">COMPARE US</span><h2>You & ${esc(person?.displayName||'a reference person')}</h2></div>${synthetic()}</div>${result.available?`<p class="small-copy muted">${esc(person.subtitle)} · ${modeName(state.mode)} · ${esc(state.asOf)} · ${RUBRIC}</p><div class="table-scroll"><table class="compare-table"><caption class="sr-only">Scores out of 100 under identical assessment conditions</caption><thead><tr><th>Measured capability</th><th>You</th><th>${esc(person.displayName.split(' ')[0])}</th><th>Difference</th></tr></thead><tbody>${result.rows.map(r=>`<tr class="${r.skill===selectedSkill?'focused-row':''}"><th scope="row">${button(skillById(r.skill).name,`skill:${r.skill}`,'text-button')}</th><td>${formatScore(r.yours)}</td><td>${formatScore(r.theirs)}</td><td>${r.gap===null?'Incompatible / unknown':`${delta(r.gap*25)} ${r.gap>0?'ahead':r.gap<0?'behind':'tied'}`}</td></tr>`).join('')}</tbody></table></div><div class="comparison-insight"><span class="eyebrow">WHAT THE MEASUREMENTS SAY</span><p>${result.gaps.length?`The largest measured separation is in <strong>${result.gaps.slice(0,2).map(r=>`${skillById(r.skill).name.toLowerCase()} (${(r.gap*25).toFixed(1)} points)`).join('</strong> and <strong>')}</strong>. That identifies where a new demonstration could matter; it does not establish why this person performs differently.`:'This person is not demonstrably ahead on any currently comparable capability. Choose another person or inspect a different capability.'}</p></div><div class="button-row">${row?.gap>0?button(`Create ${skillById(selectedSkill).name.toLowerCase()} Surpass Project ${icon('arrow')}`,`new:${selectedSkill}:${person.id}`,'btn'):button('Inspect selected capability',`skill:${selectedSkill}`,'btn outline')}${button('Inspect reference evidence',`peer-evidence:${person.id}`,'text-button')}</div>${person.permission.practices?`<div class="shared-practices"><h3>Practices intentionally shared</h3><p>Fictional, authored bundles. Choosing one cannot copy this person’s skill, identity, reputation or score.</p>${person.sharedBundles.map(id=>{const b=perspectives.find(b=>b.id===id),gap=result.rows.find(r=>r.skill===b.skill)?.gap;return gap>0?button(`${b.title} ${icon('up')}`,`perspective:${id}:${person.id}`,'btn outline small'):'';}).join('')}</div>`:''}`:`<div class="withheld"><h3>Comparison unavailable</h3><p>${esc(result.reason)}</p></div>`}</section></div><section class="section"><div class="section-heading"><div><h2>People near your current evidence</h2><p>Nearest in ${skillById(selectedSkill).name.toLowerCase()}, not inferred similarity as people.</p></div></div><div class="nearby-grid">${near.map(({p,score})=>button(`<span class="person-avatar">${initials(p.displayName)}</span><strong>${p.displayName}</strong><span>${formatScore(score)} / 100</span><small>Synthetic participant</small>`,`person:${p.id}:${selectedSkill}`,`card nearby-person ${person?.id===p.id?'selected':''}`)).join('')}</div></section>`;
}
function projectsView(){const visible=state.projects.filter(p=>projectFilter==='All'||p.status===projectFilter.toLowerCase());return `${pageHead('CROSS A MEASURABLE THRESHOLD','Surpass Projects.','The target stays specific. The evidence does the moving.',button(`${icon('plus')} Create a project`,'new','btn'))}<div class="notice">${icon('info')} Completing a checklist does not change your score or rank. Only accepted, eligible evidence can do that.</div><div class="filter-row" role="group" aria-label="Project status">${['All','Active','Review','Complete'].map(f=>button(f,`filter:${f}`,`filter-chip ${projectFilter===f?'active':''}`,`aria-pressed="${projectFilter===f}"`)).join('')}</div><div class="growth-grid">${visible.length?visible.map(p=>`<article class="card project-card"><div class="growth-top">${tag(p.status==='complete'?'Threshold demonstrated':p.status==='review'?'Evidence awaiting review':'In progress',p.status==='complete'?'mint':'sand')}<span class="micro">${p.minutes} MIN</span></div><h3>${esc(p.title)}</h3><p>${skillById(p.skill).name} · ${modeName(p.target.mode)}</p><div class="project-target"><small>FROZEN COMPARISON TARGET</small><strong>${esc(p.target.personName||'Capability threshold')}</strong><p>${formatScore(p.target.initialScore)} → ${p.target.targetScore===null?'3 accepted demonstrations':`${formatScore(p.target.targetScore)} / 100`}</p><small>${esc(cohorts.find(c=>c.id===p.target.cohort).name)} · synthetic</small></div><p>${p.steps.filter(Boolean).length}/3 demonstration steps · ${p.origin?'Shared practices attached':'Evidence contract attached'}</p>${button(`Open project ${icon('arrow')}`,`project:${p.id}`,'btn outline full')}</article>`).join(''):`<div class="card empty-state"><h2>No projects in this view.</h2><p>A measured gap is a useful place to begin.</p>${button('Find a person just ahead','go-people','btn')}</div>`}</div>`;}
function trajectoryView(){const cutoff=Date.parse(state.asOf)-historyDays*86400000,events=state.history.filter(h=>Date.parse(h.date)>=cutoff),m=movement(state,historyDays),current=becomingIndex(state),points=events.map((h,i)=>({x:50+i*720/Math.max(1,events.length-1),y:h.modes[state.mode].score===null?null:220-h.modes[state.mode].score*.19,basket:h.modes[state.mode].basket.join(),event:i+1}));
return `${pageHead('STANDING AND MOMENTUM ARE DIFFERENT','Your movement.','See which accepted demonstrations changed the picture—and when coverage changed the picture itself.')} ${contextBar()}<div class="trajectory-toolbar"><label>History window<select id="history-days"><option value="7" ${historyDays===7?'selected':''}>7 days</option><option value="30" ${historyDays===30?'selected':''}>30 days</option><option value="90" ${historyDays===90?'selected':''}>90 days</option></select></label><p>${esc(m.note)}</p></div><div class="card trajectory-card"><div class="movement-stats"><div><span>CURRENT INDEX</span><strong>${formatIndex(current.score)}</strong></div><div><span>SAME-BASKET MOVEMENT</span><strong>${m.points===null?'Not comparable':`${delta(m.points)} pts`}</strong></div><div><span>PERCENTILE MOVEMENT</span><strong>${m.percentilePoints===null?'Not comparable':`${delta(m.percentilePoints)} pts`}</strong></div><div><span>COVERAGE NOW</span><strong>${current.coverage}%</strong></div></div><svg class="trajectory-chart" viewBox="0 0 800 260" role="img" aria-label="Index history. Exact dates, scores and coverage are listed in the table below. Horizontal spacing is by recorded event."><path d="M50 30H780M50 125H780M50 220H780" fill="none" stroke="#dfe5d9" stroke-dasharray="4 5"/><text x="5" y="34">1000</text><text x="5" y="129">500</text><text x="5" y="224">0</text>${points.map((p,i)=>{const prev=points[i-1];return p.y===null?'':`${prev&&prev.y!==null&&prev.basket===p.basket?`<line x1="${prev.x}" y1="${prev.y}" x2="${p.x}" y2="${p.y}" stroke="#254d3b" stroke-width="2.5"/>`:''}<circle cx="${p.x}" cy="${p.y}" r="5" fill="#254d3b"/>`;}).join('')}${points.map(p=>`<text x="${p.x}" y="248" text-anchor="middle">${p.event}</text>`).join('')}</svg><p class="small-copy muted">Event order, not time-scaled. Unknown scores are not plotted; lines break when the measured basket changes. Coverage changes are not claimed as growth. Historical percentiles remain unknown where the reference was not yet observed.</p></div><div class="card table-scroll section"><table class="history-table"><caption>Actual derived snapshots · ${modeName(state.mode)} · ${esc(cohortName())}</caption><thead><tr><th>Event / date</th><th>Index</th><th>Percentile</th><th>Coverage</th><th>Evidence count</th></tr></thead><tbody>${events.map((h,i)=>{const a=h.modes[state.mode],p=state.benchmarkVisible?a.percentiles[state.cohort]:null;return `<tr><th scope="row"><strong>${i+1}. ${esc(h.label)}</strong><small>${h.date}</small></th><td>${formatIndex(a.score)}</td><td>${p===null?'Unknown':ordinal(p)}</td><td>${a.coverage}%<small>${a.basket.length}/6 capabilities</small></td><td>${Object.values(a.capabilities).reduce((n,c)=>n+c.n,0)}</td></tr>`;}).join('')}</tbody></table></div><section class="section"><h2>Capability-level movement</h2><div class="dimensions-grid movement-dimensions">${skills.map(s=>{const cur=estimate(state,s.id),old=m.baseline?.modes[state.mode].capabilities[s.id];return `<article class="card dimension-card"><h3>${s.name}</h3><strong class="movement-number">${cur.score!==null&&old?.score!==null&&old?.score!==undefined?`${delta((cur.score-old.score)*25)} pts`:'Not comparable'}</strong><p>${cur.n} currently eligible demonstrations</p>${button('Inspect evidence',`skill:${s.id}`,'text-button')}</article>`;}).join('')}</div></section>`;
}
function evidenceView(){const pending=state.evidence.filter(e=>e.status==='pending'&&e.mode===state.mode),trail=state.evidence.filter(e=>e.status!=='pending'&&e.mode===state.mode);return `${pageHead('THE WORK BEHIND THE NUMBER','Evidence library.','Accept a demonstration—not a flattering description. Withdraw it when the record no longer holds.')} ${modeToggle()}<div class="notice section">${icon('info')} Every record is synthetic. Fixed fixture assessments do not analyze your notes or assess the visitor.</div><div class="section-heading"><h2>Waiting for review <span class="pill-count">${pending.length}</span></h2></div><div class="review-grid">${pending.length?pending.map(e=>`<article class="card review-card"><div class="growth-top">${tag('Pending · synthetic','sand')}<span class="micro">${e.date}</span></div><h3>${esc(e.title)}</h3><p>${skillById(e.skill).name} · ${modeName(e.mode)} · ${e.mark}/4 fixture mark</p><p class="small-copy">${esc(e.rationale)}</p><div class="button-row">${button(`Inspect & review ${icon('arrow')}`,`review:${e.id}`,'btn')}${button('Inspect capability',`skill:${e.skill}`,'text-button')}</div></article>`).join(''):`<div class="empty-inline">${icon('check')} Nothing waiting in this condition. A Surpass Project can supply the next synthetic demonstration.</div>`}</div><div class="section-heading section"><div><h2>The evidence trail</h2><p>Rubric marks, conditions, source grants and individual revocations remain visible.</p></div></div><div class="card table-scroll evidence-table"><table><caption class="sr-only">Synthetic evidence in the selected assistance condition</caption><thead><tr><th>Demonstration</th><th>Capability</th><th>Mark</th><th>Eligibility</th><th>Inspect</th></tr></thead><tbody>${trail.map(e=>`<tr><td><strong>${esc(e.title)}</strong><small>${e.date} · ${sources.find(s=>s.id===e.source).name}</small></td><td>${skillById(e.skill).name}</td><td>${e.mark} / 4</td><td>${tag(evidenceExclusion(state,e)||'Accepted & eligible',evidenceExclusion(state,e)?'sand':'mint')}</td><td>${button('View',`review:${e.id}`,'text-button',`aria-label="Inspect ${esc(e.title)}"`)}</td></tr>`).join('')}</tbody></table></div>`;}
function methodologyView(){const index=becomingIndex(state);return `${pageHead('NO BLACK BOX','Every number has a route back.','Index → dimensions → capabilities → assessments → evidence.')} ${contextBar()}<section class="method-hero"><span class="eyebrow">THE BECOMING INDEX · VERSION 2</span><h2>${formatIndex(index.score)} <small>/ 1000</small></h2><p>A fixed-weight composite of demonstrated capabilities. Not a measure of human worth, potential, personality or every part of life.</p><code>250 × Σ(capability mean × fixed weight) / Σ(observed weights)</code><p>Six capability slots, each weighted 1/6. Goals never change these weights. Unknown capabilities are excluded, not scored zero.</p></section><div class="method-grid"><section class="card method-card"><h2>Standing</h2><p>Midrank percentile = 100 × (people strictly below + half the ties) / compatible people. Comparisons use the same rubric, protocol, assistance condition and capability basket.</p><p>A low valid percentile remains visible. A missing or incompatible comparison is not invented. At least ${MIN_COHORT} comparable people are needed for aggregate placement.</p></section><section class="card method-card"><h2>Coverage & uncertainty</h2><p>Coverage is the weight of capabilities with at least ${MIN_EVIDENCE} eligible, distinct demonstrations. It is not ability. Each estimate uses up to the latest ${MAX_SAMPLES} demonstrations within ${RECENCY_DAYS} days.</p><p>The index envelope averages observed low/high marks. It is descriptive, <strong>not a confidence interval</strong>. Reliability, predictive validity and population representativeness are not calibrated.</p></section><section class="card method-card"><h2>Movement</h2><p>Accepted evidence, individual revocation and source-grant changes produce snapshots. Checklist completion, practice adoption and cohort changes do not manufacture a growth event.</p><p>Movement is compared only for the same observed basket, mode and reference version. Changing coverage can change the index without demonstrating improvement.</p></section><section class="card method-card"><h2>Conditions & population</h2><p>${esc(cohortName())}. ${esc(cohorts.find(c=>c.id===state.cohort).detail)}</p><p>Rubric ${RUBRIC}; protocol ${PROTOCOL}; ${modeName(state.mode)}. Reference ${REFERENCE_VERSION}. These are authored test fixtures, not validated population norms.</p></section></div><section class="section"><div class="section-heading"><h2>Decompose your current index</h2><span class="small-copy">${index.coverage}% coverage · ${state.asOf}</span></div>${dimensions.map(d=>`<details class="card decomposition"><summary><span>${d.name}</span><strong>${(d.weight*100).toFixed(1)}% fixed weight</strong></summary><p>Each of this dimension’s ${d.skills.length} capabilities has ${(d.weight/d.skills.length*100).toFixed(2)}% total index weight.</p>${d.skills.map(id=>{const s=skillById(id),st=estimate(state,id);return `<div class="decomposition-skill"><div><h3>${s.name}</h3><p>${s.criterion}</p><small>${st.n}/${MIN_EVIDENCE} minimum demonstrations · ${modeName(state.mode)} · ${RUBRIC}</small></div><strong>${formatScore(st.score)} / 100</strong>${button('Assessments & evidence',`skill:${id}`,'btn outline small')}</div>`;}).join('')}</details>`).join('')}</section><section class="card rubric-card section"><h2>The retained demonstration rubric</h2><div class="rubric-anchors">${[['0','Attempt observed; criterion not demonstrated'],['1','Partial result; substantive guidance required'],['2','Criterion met in a familiar task'],['3','Criterion repeated with trade-offs explained'],['4','Method transferred to an unfamiliar constraint']].map(([n,t])=>`<div><strong>${n}</strong><p>${t}</p></div>`).join('')}</div><p>Marks are task-specific and always carry an assistance condition. No evidence is not a mark of zero.</p></section><div class="data-note">${icon('info')} Unsupported life domains are not measured here. Real participant ingestion, authorization and calibration require separate implementation and validation.</div>`;}
function proposalView(){return `${pageHead('AN INDEPENDENT CONCEPT FOR THE OPENAI ECOSYSTEM','Where am I among other people?','And what would it actually take to move?')}<section class="notice"><div><strong>A simpler place to begin.</strong><p>Today starts with your interests, a concrete example and a step you choose. Your editable local record keeps the context. Guided prompts are authored, not a live AI conversation; your words are never scored. Explore demo contains the complete fictional comparative instrument described below.</p><a class="text-link" href="./docs/DISCOVERY-CONTRACT.md" target="_blank" rel="noopener">Read the interest-led contract ↗</a></div></section><section class="proposal-hero"><span class="eyebrow">BECOMING · THE FIRST-PERSON INSTRUMENT</span><h2>Know your place.<br><em>Make your next move<br>demonstrable.</em></h2><p>Becoming makes comparative placement useful: a transparent index, legitimate reference populations, people just ahead, shared practices, and Surpass Projects that return evidence to the measurement.</p></section><div class="explain-strip"><div><span class="step-number">01</span><h3>Tell the truth</h3><p>Show valid low and high percentiles directly. State what the evidence measures and who the comparison includes.</p></div><div><span class="step-number">02</span><h3>Make the gap tangible</h3><p>Find someone slightly ahead and inspect the actual measured difference—not inferred personality or motivation.</p></div><div><span class="step-number">03</span><h3>Move through evidence</h3><p>Turn the comparison into a project with a frozen target, allowed assistance, demonstration and review contract.</p></div></div><section class="card proposal-docs"><h2>The complete offering</h2>${[['PROPOSAL','Product thesis'],['ARCHITECTURE','Architecture & participant contracts'],['EVALUATION','Measurement validation plan'],['ACCEPTANCE','Acceptance criteria'],['QA','Executed verification'],['PERMISSION','Permission for OpenAI only'],['BRAND','Independent ecosystem branding'],['LICENSE-HISTORY','Earlier MIT rights & license history'],['PROVENANCE','Source lineage']].map(([f,t])=>`<a href="./docs/${f}.md" target="_blank" rel="noopener"><span>${icon('book')}<strong>${t}</strong></span>${icon('up')}</a>`).join('')}</section><section class="principle-card"><span class="icon-tile mint">${icon('check')}</span><div><h2>Offered to OpenAI. Free to build on.</h2><p>Hayden Lindley grants the defined OpenAI entities royalty-free use of new original material under the OpenAI-only license. This is not a general open-source grant. Earlier MIT rights remain intact; no affiliation, endorsement, delivery or acceptance by OpenAI is claimed.</p><div class="offering-license-links"><a href="./LICENSE" target="_blank" rel="noopener">Read the OpenAI-only license ${icon('up')}</a><a href="./licenses/MIT-legacy.txt" target="_blank" rel="noopener">Retained MIT notice ${icon('up')}</a></div></div></section><section class="card method-card"><h2>Becoming and Emergence</h2><p>Becoming is the first-person instrument: where am I, who is nearby, and what could move me? Emergence is the world-facing landscape. This implementation stands alone and does not depend on Emergence.</p></section>`;}
function render(){const views={today:()=>discoveryView(journey,journeyStage||journey.stage,journeyStatus,journeyMessage),record:()=>discoveryRecord(journey,journeyStatus,journeyMessage),board,people:peopleView,projects:projectsView,trajectory:trajectoryView,perspectives:perspectivesView,evidence:evidenceView,methodology:methodologyView,consent:consentView,proposal:proposalView};$('#app').innerHTML=shell(views[route()]());document.title=`${route()==='today'?'Today':route()==='record'?'Your record':pages.find(p=>p[0]===route())?.[2]||'Independent concept'} · Becoming`;}
function renderJourney(){render();const heading=$('h1');heading?.setAttribute('tabindex','-1');heading?.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}
function persistJourney(next){if(journeyStatus==='recovery')throw new Error('Recover or erase the unreadable record before saving new answers.');journey=next;const saved=writeJourney(journeyStorage,journey);journeyStatus=saved.ok?'saved':'session';journeyMessage=saved.message||'';journeyStage=null;}
function modal(title,body,wide=false){const d=$('#dialog');if(!d.open)returnFocus=document.activeElement?.dataset?.action||null;if(d.open)d.close();d.className=wide?'wide':'';d.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${title}</h2>${button(icon('close'),'close','icon-button','aria-label="Close dialog"')}</div><div class="dialog-body">${body}</div>`;d.showModal();}
function close(){const d=$('#dialog');if(d.open)d.close();}
function newProjectDialog(skillId,personId=null){const s=skillById(skillId)||skillById(selectedSkill),person=personById(personId)||justAhead(state,s.id)?.person;modal('Make the gap your next project.',`<p class="dialog-intro">Freeze a measurable target. Then demonstrate the difference.</p><form id="project-form" data-person="${person?.id||''}"><label class="field">Capability<select name="skill" id="project-skill">${skills.map(x=>`<option value="${x.id}" ${x.id===s.id?'selected':''}>${x.name}</option>`).join('')}</select></label><label class="field">Project title<input name="title" id="project-title" required maxlength="120" value="${esc(`Surpass in ${s.name.toLowerCase()}`)}"></label><label class="field">Session length<select name="minutes"><option value="15">15 minutes</option><option value="30" selected>30 minutes</option><option value="60">60 minutes</option></select></label><div class="criterion" id="target-preview">${targetPreview(s.id,person?.id)}</div><button class="btn full" type="submit">Create Surpass Project ${icon('arrow')}</button></form><p class="fine-print dark">The cohort, person, target score, rubric, assistance condition and current evidence will be preserved in the project. A percentile increase is not guaranteed.</p>`);}
function targetPreview(skill,personId){const t=projectTarget(state,skill,personId||null);return `<span class="eyebrow">${t.type==='person'?'SYNTHETIC HUMAN COMPARATOR':t.type==='baseline'?'EVIDENCE BASELINE':'CAPABILITY THRESHOLD'}</span><h3>${esc(t.personName||'Build the evidence needed to move')}</h3><p>${skillById(skill).name} · ${formatScore(t.initialScore)} → ${t.targetScore===null?'3 accepted demonstrations':`${formatScore(t.targetScore)} / 100`}</p><small>${esc(cohortName())} · ${modeName(state.mode)} · ${RUBRIC}<br>${t.targetPercentile===null?'No valid percentile implication is available.':`Illustrative placement: ${ordinal(t.initialPercentile)} → approximately ${ordinal(t.targetPercentile)} percentile in this frozen reference.`}<br>${esc(t.success)}</small>`;}

function skillDialog(id){const s=skillById(id),st=estimate(state,id),c=comparison(state,id),next=justAhead(state,id);if(!s)return;modal(s.name,`<div class="dialog-subline">${tag(modeName(state.mode),s.color)}${tag('Synthetic evidence','sand')}<span>${state.asOf}</span></div><div class="capability-dialog-metrics"><div><strong>${formatScore(st.score)}</strong><span>/ 100</span></div><div><strong>${c.available?`${ordinal(c.percentile)} percentile`:'Not ranked'}</strong><small>${esc(cohortName())}</small></div></div><p>${c.available?`${c.stronger} of ${c.n} reference people currently demonstrate stronger performance here.`:esc(c.reason)}</p><div class="criterion"><span class="eyebrow">WHAT YOU MUST DEMONSTRATE</span><p>${s.criterion}</p></div><p class="small-copy">${st.n} eligible demonstrations · ${st.coverage}% coverage · ${RUBRIC} · ${PROTOCOL}<br>Observed marks ${st.range?st.range.join('–'):'unknown'} / 4. Descriptive range; confidence is not calibrated.</p><div class="mini-evidence">${st.evidence.map(e=>`<div><span><strong>${esc(e.title)}</strong><small>${e.date} · ${sources.find(s=>s.id===e.source).name} · ${esc(e.provenance)}</small></span><b>${e.mark}/4</b>${button('Inspect',`review:${e.id}`,'text-button')}</div>`).join('')||'<p>No eligible evidence in this condition. Unknown is not zero.</p>'}</div><div class="button-row">${next?button(`Compare with ${next.person.displayName}`,`person:${next.person.id}:${id}`,'btn'):''}${button('Create Surpass Project',`new:${id}`,'btn outline')}</div>`,true);}
function projectDialog(id){const p=state.projects.find(p=>p.id===id);if(!p)return;const t=p.target,s=skillById(p.skill);modal(esc(p.title),`<div class="dialog-subline">${tag(s.name,s.color)}${tag(modeName(t.mode))}${tag(p.status==='complete'?'Threshold demonstrated':p.status==='review'?'Awaiting review':'In progress','sand')}</div><div class="criterion"><span class="eyebrow">FROZEN COMPARISON & EVIDENCE CONTRACT</span><h3>${esc(t.personName||'Capability threshold')} · synthetic</h3><p>${formatScore(t.initialScore)} → ${t.targetScore===null?'3 accepted demonstrations':`${formatScore(t.targetScore)} / 100`}</p><p>${esc(t.criterion)}</p><small>${esc(cohorts.find(c=>c.id===t.cohort).name)} · ${t.asOf}<br>${t.rubric} · ${t.protocol}<br>${t.targetPercentile===null?'Rank implication unavailable':`Illustrative percentile target: ${ordinal(t.initialPercentile)} → ${ordinal(t.targetPercentile)}`}<br>Starting evidence: ${t.evidenceIds.length} accepted records. ${esc(t.success)}</small></div>${p.origin?`<div class="adopted-practices"><strong>Practices you chose</strong>${p.origin.practices.map(i=>`<p>${esc(perspectives.find(b=>b.id===p.origin.bundle).practices[i])}</p>`).join('')}</div>`:''}<div class="project-steps">${[['Frame','Name the claim, audience, constraint and comparison gap.'],['Demonstrate','Produce an inspectable artifact under the allowed assistance condition.'],['Transfer','Repeat the method on an unfamiliar constraint and explain the trade-off.']].map(([title,description],i)=>`<label class="project-step"><input type="checkbox" data-step="${i}" data-project="${p.id}" ${p.steps[i]?'checked':''} ${p.status!=='active'?'disabled':''}><span><strong>${i+1}. ${title}</strong><small>${description}</small></span></label>`).join('')}</div><label class="field">Your reflection <span class="muted">Optional · browser-local · never automatically scored</span><textarea maxlength="4000" rows="3" id="reflection" data-project="${p.id}" placeholder="What did you demonstrate? What assistance was used?">${esc(p.reflection)}</textarea></label><div class="button-row">${button(`${icon('download')} Download brief`,`brief:${p.id}`,'btn outline')}${p.status==='active'?button('Replay synthetic demonstration',`replay:${p.id}`,'btn',p.steps.every(Boolean)&&state.mode===t.mode?'':'disabled'):p.status==='review'?button('Review evidence','go-evidence','btn'):tag('Threshold supported by accepted evidence','mint')}</div><p class="fine-print dark">Replay supplies a predefined fictional 4/4 transfer demonstration in ${modeName(t.mode).toLowerCase()} mode. It does not analyze your notes. ${state.mode!==t.mode?'Switch the interface to the project’s frozen condition to replay. ':''}${t.rankNotice} Checklist completion never changes rank.</p>`,true);}
function evidenceDialog(id){const e=state.evidence.find(e=>e.id===id);if(!e)return;const exclusion=evidenceExclusion(state,e),s=skillById(e.skill);modal('Inspect the demonstration.',`<div class="dialog-subline">${tag('Synthetic record','sand')}${tag(modeName(e.mode))}${tag(e.status)}</div><h3>${esc(e.title)}</h3><div class="assessment-mark"><strong>${e.mark}</strong><span>/ 4 rubric mark</span></div><p>${esc(e.rationale)}</p><div class="criterion"><span class="eyebrow">CAPABILITY CRITERION</span><p>${s.criterion}</p></div><dl class="evidence-facts"><dt>Rubric / protocol</dt><dd>${e.rubric}<br>${e.protocol}</dd><dt>Observed</dt><dd>${e.date} · ${RECENCY_DAYS}-day window</dd><dt>Source grant</dt><dd>${sources.find(s=>s.id===e.source).name} · ${state.sources[e.source]?'active':'disconnected'}</dd><dt>Provenance</dt><dd>${esc(e.provenance)}</dd><dt>Assessor</dt><dd>${esc(e.assessor)}</dd><dt>Demonstration ID</dt><dd>${esc(e.demonstrationId)}</dd><dt>Eligibility</dt><dd>${esc(exclusion||'Accepted and eligible')}</dd></dl>${e.status==='pending'?`<label class="field">Review note <span class="muted">Optional · not scored</span><textarea id="review-note" maxlength="1000" rows="2" placeholder="Check the source, assistance condition and criterion."></textarea></label><div class="button-row">${button('Accept evidence',`accept:${e.id}`,'btn',evidenceExclusion(state,{...e,status:'accepted'})?'disabled':'')}${button('Reject / request revision',`reject:${e.id}`,'btn outline')}</div><p class="fine-print dark">Acceptance adds this eligible demonstration to the estimate. It does not assert that the fixture measures you.</p>`:`<p class="small-copy">Review note: ${esc(e.reviewNote||'No note recorded.')}</p>${e.status==='accepted'?button('Revoke this evidence',`revoke:${e.id}`,'btn outline danger'):''}`}`,true);}
function peerEvidenceDialog(id){const person=personById(id),e=person?.observations?.[state.mode]?.[selectedSkill];if(!e)return;modal(`${esc(person.displayName)}: reference evidence`,`${synthetic()}<p class="dialog-intro">${skillById(selectedSkill).name} · ${modeName(state.mode)}</p><p>Mean ${formatScore(participantEstimate(person,selectedSkill,state.mode,state.asOf))} / 100 from ${e.marks.length} accepted synthetic rubric observations.</p><div class="reference-marks">${e.marks.map((mark,i)=>`<span title="Demonstration ${i+1}">${mark}/4</span>`).join('')}</div><dl class="evidence-facts"><dt>Observed</dt><dd>${e.observedAt}</dd><dt>Version</dt><dd>${e.rubric}<br>${e.protocol}</dd><dt>Source</dt><dd>${esc(e.source)}</dd><dt>Assessment</dt><dd>${esc(e.assessmentId)}</dd><dt>Permission basis</dt><dd>${esc(person.permission.basis)}</dd></dl><p>${esc(person.notice)} These marks are authored arithmetic fixtures, not evidence about a real individual.</p>`,true);}
function perspectiveDialog(id,personId=null){const p=perspectives.find(p=>p.id===id);if(!p)return;const adopted=state.adopted.find(a=>a.id===id);perspectivePerson=personId;modal(p.title,`<div class="perspective-dialog-art ${p.color} ${p.shape}" aria-hidden="true"><i></i><i></i><i></i></div><p class="dialog-intro">${p.subtitle}</p><p class="small-copy muted">${p.author} · fictional creator · practices from the MIT-licensed 0.2.0 release, v1.0.${personId?` Shared by ${esc(personById(personId).displayName)}, a synthetic participant.`:''}</p><form id="perspective-form" data-perspective="${id}"><div class="project-steps">${p.practices.map((text,i)=>`<label class="project-step"><input type="checkbox" name="practice" value="${i}" ${adopted?adopted.practices.includes(i)?'checked disabled':'disabled':'checked'}><span><strong>${text}</strong></span></label>`).join('')}</div><div class="criterion"><span class="eyebrow">TASTES ARE NOT GRADES</span><p>${p.tastes.join(' · ')}</p><small>${p.tension}</small></div>${adopted?button('Remove from practice library',`unadopt:${id}`,'btn outline full'):'<button class="btn full" type="submit">Adopt practices & create Surpass Project</button>'}</form><p class="fine-print dark">Adopting a practice changes neither skill nor index nor rank. Existing project provenance survives removal from your practice library.</p>`);}
function tour(){modal('Know your place. Change it.',`<p class="dialog-intro">Follow one honest loop from comparison to evidence-backed movement.</p><div class="tour-steps">${[['01','See your standing','Read the index, named cohort, coverage and movement separately.'],['02','Find someone just ahead','Select a capability and inspect the specific gap. All people here are synthetic.'],['03','Create a Surpass Project','Freeze the person, target, current evidence, rubric and allowed assistance.'],['04','Demonstrate, then review','Complete the steps and replay the supplied fictional demonstration. Accept or reject its evidence.'],['05','See legitimate movement','Return to standing and history. Revoke evidence to see the correction propagate.']].map(([n,t,d])=>`<div><span class="step-number">${n}</span><div><h3>${t}</h3><p>${d}</p></div></div>`).join('')}</div><div class="notice">${icon('info')} No real person is scored. No private account, model, analytics or backend is connected.</div>${button('Explore Becoming','close','btn full')}`,true);}
function restoreActionFocus(action){if(!action)return;const el=[...document.querySelectorAll('[data-action]')].find(e=>e.dataset.action===action&&e.getClientRects().length);(el||$('#main'))?.focus({preventScroll:true});}
document.addEventListener('click',event=>{const docLink=event.target.closest('a[href^="./docs/"],a[href="./LICENSE"],a[href="./licenses/MIT-legacy.txt"]');if(docLink&&window.BECOMING_DOCS){event.preventDefault();const name=docLink.getAttribute('href').split('/').pop(),text=window.BECOMING_DOCS[name];if(text)download(name,text,name.endsWith('.md')?'text/markdown':'text/plain');return;}
const el=event.target.closest('[data-action]');if(!el||el.disabled)return;const [action,id,extra]=el.dataset.action.split(':');try{switch(action){
case 'journey-example':{const input=$('#journey-answer');if(input){input.value=discoveryExample(id,Number(extra));input.focus();}break;}
case 'journey-next':modal('What would you like to try next?',`<p class="dialog-intro">Your previous step, what happened, and its uncertainty will stay in Your record. Choose the next manageable action in your own words.</p><form id="journey-next-form"><label class="field">Next action<textarea name="answer" required maxlength="1500" rows="4" placeholder="Next, I’ll…"></textarea></label><p id="journey-next-error" class="form-error" role="alert"></p><button class="btn full" type="submit">Save this next step</button></form>`);break;
case 'journey-remove-attempt':modal('Remove this saved attempt?',`<p>This removes the archived action, original context and result. Your current next step stays. Download a full backup first if you want to keep a copy.</p><div class="button-row">${button('Keep attempt','close','btn outline')}${button('Remove saved attempt',`journey-confirm-remove:${id}`,'btn danger')}</div>`);break;
case 'journey-confirm-remove':persistJourney(removeAttempt(journey,id));close();renderJourney();toast('Saved attempt removed. Your current next step is unchanged.');break;
case 'journey-step':modal('What’s the next manageable step?',`<p class="dialog-intro">Keep the direction and reward you chose. Make this step smaller, different, or a continuation of what you tried.</p><form id="journey-form" data-stage="action"><label class="field">Your next step<textarea name="answer" id="journey-answer" required maxlength="1500" rows="4">${esc(journey.nextStep)}</textarea></label><p id="journey-error" class="form-error" role="alert"></p><button class="btn full" type="submit">Keep this step</button></form>`);break;
case 'journey-reflect':journeyStage='reflection';renderJourney();break;
case 'journey-edit':if(journeyStatus!=='recovery')modal('Make the record yours.',discoveryEditForm(journey),true);break;
case 'journey-controls':modal('Your record, under your control.',discoveryControls(journeyStatus));break;
case 'journey-export':download('becoming-local-record.json',exportJourney(journey));toast('Full local record downloaded, including your private answers. Nothing was uploaded.');break;
case 'journey-recovery':if(journeyLoad.raw!==undefined)download('becoming-original-recovery.json',journeyLoad.raw);else toast('No unreadable saved data is available.');break;
case 'journey-clear-result':modal('Clear the recorded result?',`<p>This removes what happened and your conclusion about it. Your example, direction and next step stay. The old result text is not kept in the change log.</p><div class="button-row">${button('Keep result','close','btn outline')}${button('Clear result','journey-confirm-clear-result','btn')}</div>`);break;
case 'journey-confirm-clear-result':persistJourney(correctJourney(journey,{outcome:'',evidenceStatus:'unreviewed'}));close();renderJourney();toast('Recorded result cleared. Your next step is ready to try again.');break;
case 'journey-delete':modal('Erase your local record?',`<p>This removes your saved answers, example, next step and reflections from this browser. This cannot be undone here. Downloaded backups and the fictional demo are unaffected.</p><div class="button-row">${button('Keep my record','close','btn outline')}${button('Erase my record','journey-confirm-delete','btn danger')}</div>`);break;
case 'journey-confirm-delete':{const result=deleteJourney(journeyStorage);if(!result.ok){toast(result.message||'Could not erase saved data. Your record is unchanged.');break;}journey=freshJourney();journeyLoad={record:journey,status:'new'};journeyStatus='new';journeyMessage='';journeyStage=null;close();navigate('today');renderJourney();toast('Your local record was erased. Downloaded copies and the fictional demo are unchanged.');break;}
case 'journey-confirm-import':{if(!pendingJourneyImport)break;const result=writeJourney(journeyStorage,pendingJourneyImport);if(!result.ok){toast(result.message||'Could not restore the backup. Current saved data is unchanged.');break;}journey=pendingJourneyImport;pendingJourneyImport=null;journeyLoad={record:journey,status:'saved'};journeyStatus='saved';journeyMessage='';journeyStage=null;close();navigate('today');renderJourney();toast('Your backup was restored in this browser.');break;}
case 'close':close();break;
case 'tour':tour();break;
case 'new':newProjectDialog(id,extra);break;
case 'skill':skillDialog(id);break;
case 'map':modal('Your capability constellation.',mapView()+'<p class="small-copy muted">Positions are thematic, not statistical. Select a capability to inspect its evidence.</p>',true);break;
case 'person':selectedPersonId=id;selectedSkill=extra||selectedSkill;close();navigate('people');break;
case 'mode':state.mode=id;selectedPersonId=null;save();render();restoreActionFocus(el.dataset.action);toast(`Showing ${modeName(id).toLowerCase()} evidence and comparisons.`);break;
case 'filter':projectFilter=id;render();restoreActionFocus(el.dataset.action);break;
case 'project':projectDialog(id);break;
case 'perspective':perspectiveDialog(id,extra);break;
case 'unadopt':state.adopted=state.adopted.filter(a=>a.id!==id);save();close();render();toast('Practices removed. Existing project targets and evidence are unchanged.');break;
case 'replay':replayAssessment(state,id,state.mode);save();close();navigate('evidence');toast('Synthetic evidence is pending. Your standing has not changed.');break;
case 'review':evidenceDialog(id);break;
case 'peer-evidence':peerEvidenceDialog(id);break;
case 'accept':case 'reject':{const before=becomingIndex(state).score;reviewEvidence(state,id,action==='accept'?'accepted':'rejected',$('#review-note')?.value||'');save();close();render();const after=becomingIndex(state).score;toast(action==='accept'?`Evidence accepted. Index ${before===null?'unknown':Math.round(before)} → ${after===null?'unknown':Math.round(after)}. Inspect movement for the details.`:'Evidence rejected. No capability estimate changed.');break;}
case 'revoke':modal('Revoke this evidence?',`<p>The record remains in the audit trail but no longer contributes to any estimate. A project may reopen if its threshold is no longer supported.</p><div class="button-row">${button('Cancel','close','btn outline')}${button('Revoke evidence',`confirm-revoke:${id}`,'btn danger')}</div>`);break;
case 'confirm-revoke':revokeEvidence(state,id);save();close();render();toast('Evidence revoked. Dependent estimates, project status and trajectory updated.');break;
case 'go-evidence':close();navigate('evidence');break;
case 'go-methodology':close();navigate('methodology');break;
case 'go-people':close();navigate('people');break;
case 'brief':download('becoming-surpass-project.md',projectBrief(state.projects.find(p=>p.id===id)),'text/markdown');toast('Frozen project brief downloaded.');break;
case 'source':setSource(state,id,!state.sources[id]);save();render();restoreActionFocus(el.dataset.action);toast(state.sources[id]?'Source restored. Eligible evidence is included again.':'Source disconnected. Affected evidence is excluded from both assistance conditions.');break;
case 'bench-toggle':state.benchmarkVisible=!state.benchmarkVisible;save();render();restoreActionFocus(el.dataset.action);toast(state.benchmarkVisible?'Comparisons enabled.':'Comparisons paused. Evidence and projects remain available.');break;
case 'export':download('becoming-capability-packet.json',JSON.stringify(disclosure(state),null,2));toast('Selective synthetic capability packet downloaded.');break;
case 'reset':modal('Reset this local demo?',`<p>Erase local projects, reflections, reviews and grant changes. Restore the starting synthetic participant. Downloaded files are not deleted.</p><div class="button-row">${button('Cancel','close','btn outline')}${button('Erase & reset demo','confirm-reset','btn danger')}</div>`);break;
case 'confirm-reset':try{localStorage.removeItem(KEY);}catch{}state=initialState();selectedSkill='research';selectedPersonId=null;projectFilter='All';close();render();toast('Local changes erased. Starting synthetic profile restored.');break;
}}catch(error){toast(error.message);}});
document.addEventListener('submit',event=>{
if(!['journey-form','journey-edit-form','journey-next-form'].includes(event.target.id))return;
event.preventDefault();const data=new FormData(event.target);
try {if(event.target.id==='journey-next-form'){persistJourney(startNextStep(journey,data.get('answer')));close();renderJourney();toast('Previous attempt kept in Your record. New step saved.');}else if(event.target.id==='journey-form'){const stage=event.target.dataset.stage;const value=stage==='skills'?data.getAll('skill'):stage==='reflection'?{outcome:data.get('outcome'),evidenceStatus:data.get('evidenceStatus')}:data.get('answer');persistJourney(saveAnswer(journey,stage,value));if($('#dialog').open)close();renderJourney();}else{const patch=Object.fromEntries(['interest','story','direction','reward','constraints','nextStep'].map(key=>[key,data.get(key)]));patch.skills=data.getAll('skill');persistJourney(correctJourney(journey,patch));close();renderJourney();toast('Your record was updated.');}}
catch(error){const target=$(event.target.id==='journey-form'?'#journey-error':event.target.id==='journey-next-form'?'#journey-next-error':'#journey-edit-error');if(target){target.textContent=error.message;target.setAttribute('tabindex','-1');target.focus();}}
});
document.addEventListener('change',async event=>{
if(event.target.id!=='journey-import')return;
const file=event.target.files?.[0];if(!file)return;
try {if(file.size>2000000)throw new Error('This file is too large for a local-record backup.');const candidate=parseJourneyBackup(await file.text());pendingJourneyImport=candidate;modal('Replace your local record?',`<p>The checked backup contains revision ${candidate.revision}.</p><div class="criterion"><strong>${esc(candidate.interest||'No interest recorded')}</strong><p>${esc(candidate.direction||'No direction recorded yet')}</p></div><p>Restoring replaces your current local record. Export it first if you want to keep both. The fictional demo is unchanged.</p><div class="button-row">${button('Cancel','close','btn outline')}${button('Restore this backup','journey-confirm-import','btn')}</div>`);}
catch(error){pendingJourneyImport=null;const target=$('#journey-import-error');if(target){target.textContent=error.message;target.setAttribute('tabindex','-1');target.focus();}}
});
document.addEventListener('change',event=>{const el=event.target;try{
if(el.id==='cohort'){state.cohort=el.value;selectedPersonId=null;save();render();$('#cohort')?.focus();}
if(el.id==='capability-select'){selectedSkill=el.value;selectedPersonId=justAhead(state,selectedSkill)?.person.id||null;render();$('#capability-select')?.focus();}
if(el.id==='person-select'){selectedPersonId=el.value;render();$('#person-select')?.focus();}
if(el.id==='history-days'){historyDays=Number(el.value);render();$('#history-days')?.focus();}
if(el.id==='project-skill'){const person=justAhead(state,el.value)?.person;$('#project-form').dataset.person=person?.id||'';$('#project-title').value=`Surpass in ${skillById(el.value).name.toLowerCase()}`;$('#target-preview').innerHTML=targetPreview(el.value,person?.id);}
if(el.dataset.step!==undefined){const p=state.projects.find(p=>p.id===el.dataset.project);if(p?.status==='active'){p.steps[Number(el.dataset.step)]=el.checked;save();const replay=$(`[data-action="replay:${p.id}"]`);if(replay)replay.disabled=!p.steps.every(Boolean)||state.mode!==p.target.mode;render();}}
}catch(error){toast(error.message);}});
document.addEventListener('input',event=>{if(event.target.id==='reflection'){const p=state.projects.find(p=>p.id===event.target.dataset.project);if(p){p.reflection=event.target.value.slice(0,4000);save();}}});
document.addEventListener('submit',event=>{if(!['project-form','perspective-form'].includes(event.target.id))return;event.preventDefault();try{const data=new FormData(event.target);let p;if(event.target.id==='project-form'){p=createProject(state,{skill:data.get('skill'),title:data.get('title'),minutes:data.get('minutes'),personId:event.target.dataset.person||null});}else p=adopt(state,event.target.dataset.perspective,data.getAll('practice').map(Number),perspectivePerson);save();close();projectFilter='All';navigate('projects');projectDialog(p.id);toast('Surpass Project created. Scores and rank are unchanged.');}catch(error){toast(error.message);}});
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'instant'});if(!$('#dialog').open)$('#main').focus({preventScroll:true});});
$('#dialog').addEventListener('close',()=>{if(!$('#dialog').open)restoreActionFocus(returnFocus);});
// Keep keyboard traversal inside the current modal, including dynamic replacements.
$('#dialog').addEventListener('keydown',event=>{
  if(event.key!=='Tab')return;
  const dialog=event.currentTarget;
  const focusable=[...dialog.querySelectorAll('button:not(:disabled),a[href],input:not(:disabled),select:not(:disabled),textarea:not(:disabled),summary,[tabindex="0"]')].filter(el=>el.getClientRects().length);
  const first=focusable[0],last=focusable.at(-1);
  if(!first){event.preventDefault();return;}
  if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}
  else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}
});
$('#dialog').addEventListener('click',event=>{if(event.target===$('#dialog')){const r=event.target.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)close();}});
render();if(storageNotice)toast(storageNotice);
